        V vertex = target.getVertex(i);
        resultMap.put(vertex.getId(), vertex);
    }

    // Get the number of edges in the target graph
    int numEdges = target.getNumEdges();

    // Create a new edge for each edge in the target graph
    for (int i = 0; i < numEdges; i++) {
        E edge = target.getEdge(i);
        V source = resultMap.get(edge.getSourceId());
        V target = resultMap.get(edge.getTargetId());
        resultMap.put(edge.getId(), edge);
    }
}

