public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        return lb;
    }

    // Get the number of bytes in the string
    int strLen = str.length();

    // Write the length of the string
    lb.writeVarint32(strLen);

    // Write the bytes of the string
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c <= 0x007F) {
            lb.writeByte((byte) c);
        } else if (c <= 0x07FF) {
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else if (c <= 0xFFFF) {
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else {
            lb.writeByte((byte) (0xF0 | (c >> 18)));
            lb.writeByte((byte) (0x80 | ((c >> 12) & 0x3F)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

