public Converter lookup(Class<?> clazz) {
    // Check if a Converter is registered for the specified class
    Converter converter = converters.get(clazz);
    if (converter != null) {
        return converter;
    }

    // If no Converter is registered, check if the class has a registered Converter
    // by looking up the class hierarchy
    for (Class<?> superclass = clazz.getSuperclass(); superclass != null; superclass = superclass.getSuperclass()) {
        converter = converters.get(superclass);
        if (converter != null) {
            return converter;
        }
    }

    // If no Converter is found, return null
    return null;
}

