public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    if (desiredCapacity == 0) {
      return 1;
    }

    // Find the closest prime number that is >= desiredCapacity
    int prime = 2;
    while (prime < desiredCapacity) {
      prime += 2;
      if (isPrime(prime)) {
        return prime;
      }
    }

    return prime;
