private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the circulator to start from the given node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Loop until we find a node that satisfies the predicate or reach the stop node
    while (circulator.hasNext() && !predicate.test(circulator.next())) {
        // If we reach the stop node, return the circulator to the stop node
        if (circulator.next() == stop) {
            return new OuterFaceCirculator(stop, dir);
        }
    }

    // If we found a node that satisfies the predicate, return the circulator to that node
    if (circulator.hasNext()) {
        return circulator;
    }

    // If we didn't find a node that satisfies the predicate, return the circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

