protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path with the first edge in the tour
    GraphPath<V, E> path = new GraphPath<>(graph, tour.iterator().next());

    // Iterate over the remaining edges in the tour
    for (E edge : tour) {
        // Add the edge to the path
        path.addEdge(edge);

        // Get the neighboring vertices of the current edge
        V from = graph.getEdgeSource(edge);
        V to = graph.getEdgeTarget(edge);

        // If the neighboring vertices are not already in the path, add them
        if (!path.containsVertex(from)) {
            path.addVertex(from);
        }
        if (!path.containsVertex(to)) {
            path.addVertex(to);
        }
    }

    return path;
}

