public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is null or empty
    if (path == null || path.isEmpty()) {
        return relativePath;
    }

    // Check if the relative path is null or empty
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array list to store the combined path components
    ArrayList<String> combinedPathComponents = new ArrayList<>();

    // Iterate over the path components
    for (String component : pathComponents) {
        // If the component is "..", remove the last path component from the combined path
        if (component.equals("..")) {
            if (!combinedPathComponents.isEmpty()) {
                combinedPathComponents.remove(combinedPathComponents.size() - 1);
            }
        } else {
            // Otherwise, add the component to the combined path
            combinedPathComponents.add(component);
        }
    }

    // Iterate over the relative path components
    for (String component : relativePathComponents) {
        // If the component is "..", remove the last path component from the combined path
        if (component.equals("..")) {
            if (!combinedPathComponents.isEmpty()) {
                combinedPathComponents.remove(combinedPathComponents.size() - 1);
            }
        } else {
            // Otherwise, add the component to the combined path
            combinedPathComponents.add(component);
        }
    }

    // Join the combined path components into a single string
    String combinedPath = String.join("/", combinedPathComponents);

    // Return the combined path
    return combinedPath;
}

