    } else {
        // If the current node is not virtual, get the next node
        Node nextNode = getNextNode(currentNode);
        // If the next node is also not virtual, return an edge from the current node to the next node
        if (!nextNode.isVirtual()) {
            return new Edge(currentNode, nextNode);
        } else {
            // If the next node is virtual, get its real counterpart
            nextNode = nextNode.getRealCounterpart();
            // Return an edge from the current node to the real next node
            return new Edge(currentNode, nextNode);
        }
    }
}

public static boolean substringMatch(String str, int index, String substring) {
    if (str == null || index < 0 || substring == null || index + substring.length() > str.length()) {
        return false;
    }

    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
    // Get the message to be logged
    String message = event.getMessage();

    // Get the list of connected clients
    List<Client> clients = getClients();

    // Iterate over the list of clients and write the message to each one
    for (Client client : clients) {
        try {
            // Write the message to the client
            client.write(message);
        } catch (IOException e) {
            // If an exception occurs while writing to the client, remove it from the list of connected clients
            clients.remove(client);
        }
    }
}

