public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    // Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new FileNotFoundException("File not found or not readable: " + file.getAbsolutePath());
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges are not valid");
    }

    // Create a new list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Open the file as a buffered reader
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        // Read the first line of the file
        String line = reader.readLine();

        // Loop through the lines of the file
        while (line != null) {
            // Check if the line is a thread snapshot line
            if (line.startsWith("ThreadSnapshot")) {
                // Parse the thread snapshot from the line
                ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);

                // Check if the thread snapshot is within the time range
                if (isWithinTimeRange(threadSnapshot, timeRanges)) {
                    // Add the thread snapshot to the list
                    threadSnapshots.add(threadSnapshot);
                }
            }

            // Read the next line
            line = reader.readLine();
        }
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}
